import java.time.Instant;
import java.time.ZoneOffset;
import java.time.LocalDateTime;

// Current epoch in milliseconds — long type
long nowMillis = System.currentTimeMillis();
long nowSeconds = nowMillis / 1000;

// long (ms) → Instant
Instant instant = Instant.ofEpochMilli(1700000000000L);

// long (s) → LocalDateTime UTC
LocalDateTime dt = LocalDateTime.ofEpochSecond(1700000000L, 0, ZoneOffset.UTC);

// LocalDateTime → epoch seconds
long epoch = dt.toEpochSecond(ZoneOffset.UTC);
